def merge_ranges(ranges):
    # Filter out empty ranges
    filtered = []
    for r in ranges:
        start, end = r[0], r[1]
        if start < end:
            filtered.append((start, end))
    filtered.sort(key=lambda x: x[0])
    merged = []
    for r in filtered:
        if not merged:
            merged.append([r[0], r[1]])
        else:
            last = merged[-1]
            if r[0] <= last[1]:
                last[1] = max(last[1], r[1])
            else:
                merged.append([r[0], r[1]])
    result = [tuple(item) for item in merged]
    return result

import heapq
def topological(edges, nodes):
    graph = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}
    seen = set()
    for u, v in edges:
        if (u, v) in seen:
            continue
        seen.add((u, v))
        if u in graph and v in graph:
            graph[u].append(v)
            indegree[v] += 1
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)
    if len(result) != len(nodes):
        raise ValueError("Cycle")
    return result

def lru(capacity, operations):
    if capacity == 0:
        results = []
        for op in operations:
            if op[0] == "get":
                results.append(-1)
        return results
    cache = {}
    order = []  # least recent first
    results = []
    for op in operations:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                cache[key] = value
                order.remove(key)
                order.append(key)
            else:
                if len(cache) >= capacity:
                    lru_key = order.pop(0)
                    del cache[lru_key]
                cache[key] = value
                order.append(key)
        elif op[0] == "get":
            _, key = op
            if key in cache:
                order.remove(key)
                order.append(key)
                results.append(cache[key])
            else:
                results.append(-1)
    return results

def flatten(value):
    if isinstance(value, (list, tuple)):
        result = []
        for item in value:
            result.extend(flatten(item))
        return result
    else:
        return [value]

