def shortest(graph, start, end):
    if start == end:
        return 0
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heapq.heappop(heap)
        if node == end:
            return d
        for neighbor, weight in graph.get(node, []):
            nd = d + weight
            if neighbor not in dist or nd < dist[neighbor]:
                dist[neighbor] = nd
                heapq.heappush(heap, (nd, neighbor))
    return None

from collections import deque
def window_max(values, k):
    if k <= 0:
        raise ValueError("k must be positive")
    if k > len(values):
        return []
    dq = deque()
    result = []
    for i, val in enumerate(values):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and values[dq[-1]] < val:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(values[dq[0]])
    return result

def rate_limit(events, limit, window):
    if limit == 0:
        return [False] * len(events)
    result = []
    key_windows = {}
    for timestamp, key in events:
        if key not in key_windows:
            key_windows[key] = []
        timestamps = key_windows[key]
        # Remove outdated accepted events
        while timestamps and timestamps[0] <= timestamp - window:
            timestamps.pop(0)
        if len(timestamps) < limit:
            result.append(True)
            timestamps.append(timestamp)
        else:
            result.append(False)
    return result

def stable_unique(values):
