    for v in values:
        for item in result:
            if item == v:
                break
        else:
            result.append(v)
    return result

def parse_duration(text):
    if not text:
        raise ValueError("Empty input")
    total = 0
    i = 0
    n = len(text)
    while i < n:
        if not text[i].isdigit():
            raise ValueError("Malformed input")
        num = 0
        while i < n and text[i].isdigit():
            num = num * 10 + ord(text[i]) - ord('0')
            i += 1
        if i >= n or text[i] not in 'hms':
            raise ValueError("Malformed input")
        unit = text[i]
        i += 1
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num * 1
        else:
            raise ValueError("Malformed input")
    return total

def paginate(items, after, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    # Sort items by id
    sorted_items = sorted(items, key=lambda x: x['id'])
    # Filter items with id > after
    filtered = []
    for item in sorted_items:
        item_id = item['id']
        if after is not None and item_id <= after:
            continue
        filtered.append(item)
    # Take up to limit items for the page
    page = filtered[:limit]
    # Determine next_cursor
    if len(filtered) > len(page):
        # More items remain beyond the page
        if page:
            next_cursor = page[-1]['id']
        else:
            next_cursor = None
    else:
        next_cursor = None
    return (page, next_cursor)

