import io
def csv_records(text):
    if not text:
        return []
    reader = csv.reader(io.StringIO(text))
    rows = list(reader)
    if not rows:
        return []
    headers = rows[0]
    if len(headers) != len(set(headers)):
        raise ValueError("Duplicate headers")
    records = []
    for row in rows[1:]:
        if len(row) != len(headers):
            raise ValueError("Row has different number of fields")
        records.append({headers[i]: row[i] for i in range(len(headers))})
    return records

def version_sort(versions):
    def normalize(v):
        parts = []
        for p in v.split('.'):
            parts.append(int(p))
        # Remove trailing zero segments
        while parts and parts[-1] == 0:
            parts.pop()
        return parts
    return sorted(versions, key=normalize)

def schedule(jobs):
    # sort jobs by end time without mutating original jobs
    sorted_jobs = sorted(jobs, key=lambda x: x[1])
    n = len(sorted_jobs)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        start, end, profit = sorted_jobs[i-1]
        best_prev = 0
        for j in range(i-1):
            if sorted_jobs[j][1] <= start:
                if dp[j+1] > best_prev:
                    best_prev = dp[j+1]
        dp[i] = max(dp[i-1], profit + best_prev)
    return dp[n]

def memo_cycle(definitions, name):
    visited = set()
    memo = {}
    def dfs(current):
        if current in memo:
            return memo[current]
        if current in visited:
            raise ValueError()
        visited.add(current)
        if current not in definitions:
            raise ValueError()
        val = definitions[current]
        if isinstance(val, int):
            result = val
        elif isinstance(val, list):
            total = 0
            for dep in val:
                dep_val = dfs(dep)
                total += dep_val
            result = total
        else:
            raise ValueError()
        visited.remove(current)
        memo[current] = result
        return result
    return dfs(name)
